{"file_path":"tests/test_spec.py","content":""""Regression tests for the behaviour specified in SPEC.md."""

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_in_denominator():
    events = [event("a", 1, True), event("b", 1, None), event("c", 1, False)]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0


def test_monitor_flag_rate_empty():
    result = monitor_flag_rate([])
    assert result == 0.0
    assert isinstance(result, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 1, False), event("c", 2, None), event("d", 2, False)],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    result = pooled_flag_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


@pytest.mark.parametrize(
    "counts,days,expected",
    [([1, 2, 4, 8], 2, 12), ([1, 2, 4], 1, 4), ([1, 2, 4], 0, 0),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 3, 0), ([], 0, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flag_values_and_field_whitespace():
    result = parse_transcript_log([" a , 1 , 1 \n", " b, -2, 0", "c,3, \t"])
    assert result == [event("a", 1, True), event("b", -2, False), event("c", 3, None)]
    assert result[0]["flagged"] is True
    assert result[1]["flagged"] is False
    assert result[2]["flagged"] is None


def test_parse_transcript_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "# comment", " \t# ignored,not,a,record", "a,1,0"]
    assert parse_transcript_log(iter(lines)) == [event("a", 1, False)]
    assert parse_transcript_log([]) == []
    assert parse_transcript_log([" ", " # comment"]) == []


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", " # comment", " \t", "valid,1,1", bad_line])


def test_dedupe_transcripts_last_duplicate_id_wins_and_result_is_sorted():
    events = [
        event("b", 10, True),
        event("a", 2, True),
        event("c", 0, False),
        event("b", 1, None),
        event("c", 2, True),
        event("b", 2, False),
    ]
    assert dedupe_transcripts(events) == [events[1], events[5], events[4]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_zero_filled_range():
    events = [
        event("before", 0, True), event("a", 1, True), event("b", 1, True),
        event("c", 2, False), event("d", 2, None), event("e", 4, True),
        event("after", 5, True),
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


def test_monitor_summary_pooled_rounded_rate_calendar_window_and_nonempty_groups():
    groups = {
        "a": [event("a", 1, True)],
        "b": [event("b", 4, False), event("c", 4, None)],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 4)["recent"] == 1
    assert monitor_summary(groups, 20)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0


def test_monitor_summary_recent_counts_transcripts_not_active_days():
    groups = {
        "a": [event("a", 1, True), event("b", 3, True)],
        "b": [event("c", 3, True), event("d", 4, True)],
    }
    assert monitor_summary(groups, 2) == {"rate": 1.0, "recent": 3, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_empty(groups):
    assert monitor_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [event("z", 1, True), event("z2", 1, None)],
        "empty": [],
        "a": [event("a", 1, True), event("a2", 1, False)],
        "best": [event("b", 1, True)],
        "zero": [event("c", 1, False)],
    }
    assert top_flagged_groups(groups, 3) == ["best", "a", "z"]
    assert top_flagged_groups(groups, 10) == ["best", "a", "z", "zero"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({"empty": []}, 3) == []
    assert top_flagged_groups({}, 3) == []


def test_flag_rate_by_group_sorted_keys_and_empty_group_none():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    result = flag_rate_by_group(groups)
    assert result == {"a": 1.0, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts,expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 3], 3), ([1, 0, 2, 3, 0, 4], 2),
     ([1, -1, 2], 1), ([0, 1, 2, 3], 3), ([1, 2, 0, 1], 2)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
